function classificarIntervalo(intervalo) {
  if (intervalo.startsWith('^')) return 'caret';
  if (intervalo.startsWith('~')) return 'til';
  return 'exata';
}

const intervalos = ['^1.11.0', '~2.3.1', '1.9.0'];

for (const intervalo of intervalos) {
  console.log(`${intervalo} -> ${classificarIntervalo(intervalo)}`);
}

function dependenciasForaDoLock(packageJson, nomesNoLock) {
  const { dependencies = {}, devDependencies = {} } = packageJson;
  const nomesDeclarados = [...Object.keys(dependencies), ...Object.keys(devDependencies)];
  const noLock = new Set(nomesNoLock);

  // O npm ci nao tenta resolver nem instalar nada que nao esteja no lock file:
  // em vez disso falha de imediato, para garantir que a instalacao e sempre
  // identica a que foi validada e gravada no package-lock.json. Se encontrasse
  // um pacote em falta e o instalasse por conta propria (como o npm install faria),
  // deixaria de haver garantia de reprodutibilidade entre maquinas.
  return nomesDeclarados.filter((nome) => !noLock.has(nome));
}

const packageJsonExemplo = {
  dependencies: { express: '^4.18.2', dayjs: '^1.11.0' },
  devDependencies: { eslint: '^8.50.0' },
};

console.log(dependenciasForaDoLock(packageJsonExemplo, ['express', 'eslint']));
// -> ['dayjs']
